import {enchantVisual} from './combat.js?v=16';
let artSerial=0;
const palette={D:['#999d9d','#596668'],C:['#98c69e','#38584b'],B:['#8cbfe0','#2c526e'],A:['#c6a1e2','#5a4078'],S:['#e9c582','#7e6538'],SS:['#9fb6ed','#3e477e'],'SS+':['#c4a8f2','#50387b'],SSS:['#edc583','#785628'],'SSS+':['#9aebe5','#306d77'],ULTRA:['#ffe1a6','#b1b9c7']};
export function itemArt(item,classId='VIG',size=64){classId=item.classId||classId;const ev=enchantVisual(item.enchant||0),glow=ev.stage?`filter:drop-shadow(0 0 ${ev.stage===5?5:ev.stage}px ${ev.color});`:'';const map={VIG:[0,null],ESP:[1,1],ARC:[2,3],BAS:[4,5],RUP:[6,null],DUE:[7,7],LAS:[8,9]},cell=item.slot==='weapon'?map[classId]?.[0]:item.slot==='secondary'?map[classId]?.[1]:item.slot==='head'?10:item.slot==='armor'?11:null;if(cell!=null)return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 100 100" aria-hidden="true" style="${glow}" class="equipmentArt enchant-${ev.stage}"><image href="assets/arsenal-atlas-v2.webp" x="${-(cell%4)*100}" y="${-Math.floor(cell/4)*100}" width="400" height="300"/></svg>`;if((item.classId||classId)==='RUP'&&item.slot==='weapon'){const q=['D','C'].includes(item.quality)?0:['B','A'].includes(item.quality)?1:['SSS+','ULTRA'].includes(item.quality)?3:2;return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 100 100" aria-hidden="true" class="equipmentArt"><image href="assets/weapon-atlas-v1.webp" x="${-(q%2)*100}" y="${-Math.floor(q/2)*100}" width="200" height="200"/></svg>`;}const [light,dark]=palette[item.quality]||palette.D,slot=item.slot;let shape='';const line=(p,w=3)=>`<path d="${p}" fill="none" stroke="${light}" stroke-width="${w}" stroke-linecap="round" stroke-linejoin="round"/>`;
if(slot==='weapon'){if(classId==='VIG')shape=line('M22 6 Q62 32 22 58 M22 6 L23 58',3)+line('M9 32H53 M47 27L55 32 47 37',2);else if(classId==='ARC')shape=line('M20 57L39 11',4)+`<path d="M40 4L50 14 38 27 30 14Z" fill="${light}"/><circle cx="40" cy="14" r="4" fill="#fff4d5"/>`;else if(classId==='RUP')shape=`<path d="M23 43L24 10 33 1 43 11 38 44Z" fill="${light}"/><path d="M31 8L30 42 35 42 36 8" fill="${dark}"/>`+line('M14 43L49 47 M29 47L27 61',5);else if(classId==='LAS')shape=`<path d="M26 46Q37 27 48 4L51 2Q44 31 31 49Z" fill="${light}"/>`+line('M22 43L36 51 M28 49L20 60',3);else if(classId==='ESP')shape=`<path d="M25 43L26 23 39 5 37 34 30 46Z" fill="${light}"/>`+line('M19 42L39 47 M27 47L25 59',4);else shape=`<path d="M29 44L31 8 37 2 40 10 34 45Z" fill="${light}"/><path d="M20 43L44 46 43 50 20 47Z" fill="#d6b982"/>`+line('M30 48L28 60',5);}
else if(slot==='secondary'){if(classId==='BAS')shape=`<path d="M13 10L32 4 51 10 49 39 32 59 15 39Z" fill="${dark}" stroke="${light}" stroke-width="3"/>`+line('M32 13V45 M22 27H42',3);else if(['ARC','LAS'].includes(classId))shape=`<circle cx="32" cy="31" r="18" fill="${dark}" stroke="${light}" stroke-width="3"/>`+line('M12 31H52 M32 11V51',2)+`<circle cx="32" cy="31" r="6" fill="${light}"/>`;else if(classId==='VIG')shape=`<path d="M21 20L45 26 39 60 18 56Z" fill="${dark}" stroke="${light}" stroke-width="2"/>`+line('M25 29L30 5 M33 30L39 6 M40 33L48 9',2);else shape=`<path d="M27 40L28 15 38 4 37 40Z" fill="${light}"/>`+line('M21 41H43 M31 42V59',4);}
else if(slot==='head')shape=`<path d="M13 36L14 20 32 5 50 20 51 36 42 51 38 33 26 33 22 51Z" fill="${dark}" stroke="${light}" stroke-width="3"/>`+line('M23 22L31 16 41 22',2);
else if(slot==='armor')shape=`<path d="M23 7L10 18 17 29 21 23 19 55 45 55 43 23 49 29 56 18 41 7 32 14Z" fill="${dark}" stroke="${light}" stroke-width="2.5"/>`+line('M32 18V47 M23 36H41',2);
else if(slot==='hands')shape=`<path d="M12 32L17 12 22 13 23 29 26 7 31 8 31 29 36 9 41 11 38 32 45 20 50 24 45 47 36 57 20 53Z" fill="${dark}" stroke="${light}" stroke-width="2.5"/>`;
else if(slot==='legs')shape=`<path d="M18 8H48L45 56H34L31 28 28 56H16Z" fill="${dark}" stroke="${light}" stroke-width="3"/>`+line('M17 16H46',2);
else if(slot==='boots')shape=`<path d="M13 9H28L27 41 19 49 7 48 9 40 14 36ZM37 11H51L50 43 43 53 29 52 31 43 38 37Z" fill="${dark}" stroke="${light}" stroke-width="3"/>`;
else if(slot==='neck')shape=line('M12 9Q8 43 32 43Q56 43 52 9',3)+`<path d="M32 35L43 47 32 59 21 47Z" fill="${light}"/>`;
else shape=`<ellipse cx="32" cy="36" rx="18" ry="21" fill="none" stroke="${light}" stroke-width="6"/><path d="M23 15L32 6 42 15 32 25Z" fill="${light}"/>`;
const enchant=item.enchant||0,key='art'+(++artSerial),decor=['armor','head','hands','legs','boots'].includes(slot)?line('M25 25L32 21 39 25 M26 37L32 41 38 37',1)+`<path d="M32 25L35 29 32 34 29 29Z" fill="${light}"/>`:slot==='weapon'?line('M33 15L32 31 M31 34L34 35',.8):'';shape=shape.replaceAll('fill="'+light+'"','fill="url(#'+key+'silver)"').replaceAll('fill="'+dark+'"','fill="url(#'+key+'body)"');return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 64 64" aria-hidden="true" class="equipmentArt"><defs><linearGradient id="${key}silver" x1="0" y1="0" x2="1" y2=".7"><stop stop-color="#edf6fa"/><stop offset=".28" stop-color="${light}"/><stop offset=".48" stop-color="#607b8b"/><stop offset=".6" stop-color="#e1eef1"/><stop offset="1" stop-color="${dark}"/></linearGradient><linearGradient id="${key}body" x1="0" x2="1" y2=".5"><stop stop-color="#0b1727"/><stop offset=".4" stop-color="${dark}"/><stop offset=".5" stop-color="${light}"/><stop offset=".57" stop-color="${dark}"/><stop offset="1" stop-color="#112033"/></linearGradient></defs><ellipse cx="32" cy="56" rx="21" ry="4" fill="#0008"/>${enchant>=10?`<circle cx="32" cy="32" r="28" fill="none" stroke="${enchant>=20?'#dcb0ff':light}" stroke-width="1" opacity=".6"/>`:''}${shape}${decor}</svg>`;}
